INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(16201, 'Proverbs 27:22', 'Proverbs', 27, 22, '&nbsp;کۀ تۀ کم عقل په لنګرۍ کښې د تخم په شان وټکوې، خو کم عقلتوب به د هغۀ نه لاړ نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16202, 'Proverbs 27:23', 'Proverbs', 27, 23, '&nbsp;د خپلو رمو په حال ځان پوهوه، او خپلو رمو ته زياته توجو ورکوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16203, 'Proverbs 27:24', 'Proverbs', 27, 24, '&nbsp;ځکه چې مال دولت هم د تل دپاره نۀ پاتې کيږى او نۀ تاج او تخت د ټولو نسلونو دپاره پاتې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16204, 'Proverbs 27:25', 'Proverbs', 27, 25, '&nbsp;کله چې ګياه ختمه شى او نوې ګياه راشنه شى او ګياه د غرونو نه راجمع کيږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16205, 'Proverbs 27:26', 'Proverbs', 27, 26, '&nbsp;نو بيا به ګډورى تا ته د کپړو دپاره وړۍ درکړى، او چېلۍ به درته د پټو د اخستو قيمت درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16206, 'Proverbs 27:27', 'Proverbs', 27, 27, '&nbsp;نو بيا به تا سره د چېلو دومره زيات پئ وى چې په هغې به خپل خاندان او وينځې ساتلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16207, 'Proverbs 28:1', 'Proverbs', 28, 1, '&nbsp;بدکاران هيڅ بې‌هيڅه تښتى کۀ څۀ هم څوک ورپسې نۀ وى، خو صادقان لکه د زمرو په شان ډاډه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16208, 'Proverbs 28:2', 'Proverbs', 28, 2, '&nbsp;هرکله چې يو مُلک باغى وى، نو د هغه مُلک ډېر حاکمان وى، خو پوهه او هوښيار انسان د مُلک نظام برقرار ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16209, 'Proverbs 28:3', 'Proverbs', 28, 3, '&nbsp;کوم مشر چې په غريبانانو باندې ظلم کوى د هغه تېز باران په شان دے چې ولاړ ټول فصل تباه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16210, 'Proverbs 28:4', 'Proverbs', 28, 4, '&nbsp;کوم خلق چې شريعت ماتوى نو په دې کار سره د بدکارانو صِفت کوى، خو هغه څوک چې د شريعت تابعدارى کوى نو هغوئ د شريرانو مخالفت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16211, 'Proverbs 28:5', 'Proverbs', 28, 5, '&nbsp;بدکاره انسانان په اِنصاف نۀ پوهيږى، خو څوک چې د مالِک خُدائ لټون کوى نو هغوئ پرې مکمل پوهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16212, 'Proverbs 28:6', 'Proverbs', 28, 6, '&nbsp;غريب صادق انسان د دوکه مار مالدار نه ښۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16213, 'Proverbs 28:7', 'Proverbs', 28, 7, '&nbsp;څوک چې په شريعت عمل کوى نو هغه يو هوښيار زوئ دے، خو څوک چې د بد اخلاقو دوستى کوى د خپل پلار د شرم باعث ګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16214, 'Proverbs 28:8', 'Proverbs', 28, 8, '&nbsp;څوک چې خپل ځان په زيات سود سره مالداره کړى خو آخر به د هغۀ مال دولت د هغه چا شى څوک چې په غريبانانو مهربانه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16215, 'Proverbs 28:9', 'Proverbs', 28, 9, '&nbsp;خُدائ پاک د هغه چا د دُعا نه نفرت کوى څوک چې د شريعت نه مخ اړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16216, 'Proverbs 28:10', 'Proverbs', 28, 10, '&nbsp;څوک چې يو نېک انسان بدکارۍ ته رهنمائى کوى نو په خپل لټ کښې به راګېر شى، خو ايمانداره انسان ته به ښۀ ميراث مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16217, 'Proverbs 28:11', 'Proverbs', 28, 11, '&nbsp;يو مالداره خپل ځان هوښيار ګڼى، خو يو غريب عقلمند د هغۀ په اصلى کردار پوهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16218, 'Proverbs 28:12', 'Proverbs', 28, 12, '&nbsp;کله چې صادقان کامياب شى، نو ټول قوم غټه خوشحالى کوى، خو کله چې د بدکارانو حکومت راشى نو هر څوک خپل ځان پټوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16219, 'Proverbs 28:13', 'Proverbs', 28, 13, '&nbsp;هر هغه څوک چې په خپله ګناه باندې پرده اچوى نو دے به کامياب نۀ شى، خو هر هغه څوک چې د ګناه اعتراف وکړى او هغه بس کړى نو په هغۀ به رحم وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16220, 'Proverbs 28:14', 'Proverbs', 28, 14, '&nbsp;بختور دے هغه څوک چې هر وخت د مالِک خُدائ نه يريږى، خو څوک چې خپل زړۀ سخت کړى نو په مصيبت کښې به راګېر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16221, 'Proverbs 28:15', 'Proverbs', 28, 15, '&nbsp;لکه د غړمبېدونکى زمرى او يا د اوږى مېلو په شان هغه بدکاره انسان دے څوک چې په بې‌وسه خلقو باندې حکومت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16222, 'Proverbs 28:16', 'Proverbs', 28, 16, '&nbsp;ناپوهه بادشاه به په خپلو خلقو ظلم کوى، خو څوک چې د حرام مال دولت نه نفرت کوى نو هغه به د ډېر وخت دپاره ژوندے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16223, 'Proverbs 28:17', 'Proverbs', 28, 17, '&nbsp;کۀ يو انسان خپل لاسونه د بل چا په وينو سرۀ کړى وى نو هغه به تر مرګه پورې مفرور وى، نو هيڅ څوک دې د دۀ مدد نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16224, 'Proverbs 28:18', 'Proverbs', 28, 18, '&nbsp;د چا کردار چې بې‌داغه وى نو هغه به بچ شى، خو د چا لارې چې غلطى وى نو ناګهانه به تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16225, 'Proverbs 28:19', 'Proverbs', 28, 19, '&nbsp;څوک چې د خپلې زمکې زميدارى کوى هغوئ سره به ډېر خوراک وى، د چا په سوچ کښې چې هوائى خيالونه ګرځى، نو سخته غريبى به پرې راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16226, 'Proverbs 28:20', 'Proverbs', 28, 20, '&nbsp;يو ايماندار کس ته به ډېر زيات برکت ورکړے شى، خو کۀ څوک زر مالداره کېدل غواړى هغۀ ته به سزا مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16227, 'Proverbs 28:21', 'Proverbs', 28, 21, '&nbsp;د چا طرفدارى کول ښۀ کار نۀ دے ځکه چې ځينې خلق به د يوې نوړۍ روټۍ دپاره غلط کار وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16228, 'Proverbs 28:22', 'Proverbs', 28, 22, '&nbsp;کنجوس انسان د دې ليواله وى چې مالداره شى او د دې نه ناخبره وى چې غربت د دۀ انتظار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16229, 'Proverbs 28:23', 'Proverbs', 28, 23, '&nbsp;څوک چې د اصلاح دپاره تنبيه کول کوى په آخر کښې به د هغه چا نه ورته زيات عزت مِلاو شى څوک چې په ژبه څټل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16230, 'Proverbs 28:24', 'Proverbs', 28, 24, '&nbsp;څوک چې د خپل پلار او مور نه غلا کوى او دے وائى چې، ”دا غلطى نۀ ده،“ نو دے د يو قاتل نه کم نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16231, 'Proverbs 28:25', 'Proverbs', 28, 25, '&nbsp;لالچى انسان جنګ جګړې جوړوى، خو څوک چې په مالِک خُدائ باندې توکل کوى هغه به آباد شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16232, 'Proverbs 28:26', 'Proverbs', 28, 26, '&nbsp;څوک چې په خپل ځان يقين کوى نو هغه کم عقل دے، خو څوک چې په هوښيارتيا سره قدم اوچتوى نو دے به بچ پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16233, 'Proverbs 28:27', 'Proverbs', 28, 27, '&nbsp;څوک چې غريبانانو له ورکړه کوى نو د هيڅ شى محتاجه به نۀ شى، خو څوک چې په دوئ باندې سترګې پټوى نو دوئ به په لعنت کښې ګرفتار شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16234, 'Proverbs 28:28', 'Proverbs', 28, 28, '&nbsp;هرکله چې حکومت د بدکارانو لاس ته ورشى، نو خلق خپل ځان پټوى، کله چې بدکاران هلاک شى نو صادقان بيا آباد شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16235, 'Proverbs 29:1', 'Proverbs', 29, 1, '&nbsp;څوک چې د ډيرې رټنې باوجود بيا هم په خپل ضد قائم وى، نو هغه به ناګهانه تباه شى او هيڅ علاج به يې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16236, 'Proverbs 29:2', 'Proverbs', 29, 2, '&nbsp;کله چې صادقان حکومت کوى، نو خلق خوشحالى کوى، خو هر کله چې بدکاره حکومت کوى، نو خلق فرياد کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16237, 'Proverbs 29:3', 'Proverbs', 29, 3, '&nbsp;کوم انسان چې د حِکمت سره مينه کوى نو هغه خپل پلار خوشحالوى، خو د کنجرو دوست خپل مال حال الوځوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16238, 'Proverbs 29:4', 'Proverbs', 29, 4, '&nbsp;په اِنصاف کولو سره يو بادشاه خپل مُلک قائموى، خو هغه څوک چې رشوت اخلى نو هغه مُلک تباه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16239, 'Proverbs 29:5', 'Proverbs', 29, 5, '&nbsp;څوک چې د خپل ګاونډى خوشامندى کوى، نو دے د هغۀ د پښو دپاره دام خوروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16240, 'Proverbs 29:6', 'Proverbs', 29, 6, '&nbsp;بدکاره انسان د خپلې ګناه په دام کښې راګېريږى، خو صادقان د خوشحالۍ سندرې وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16241, 'Proverbs 29:7', 'Proverbs', 29, 7, '&nbsp;صادقان د غريبانانو د حق خيال ساتى، خو بدکاران دغه شان سوچ او فکر نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16242, 'Proverbs 29:8', 'Proverbs', 29, 8, '&nbsp;مسخره کوونکى ښارونه راپاروى، خو هوښيار انسان غصه سړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16243, 'Proverbs 29:9', 'Proverbs', 29, 9, '&nbsp;کۀ يو هوښيار د يو بې‌وقوف خلاف د مقدمې دپاره عدالت ته روان شى نو بې‌وقوف به غصه شى او مسخرې به کوى نو بيا به څنګه صُلح راشى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16244, 'Proverbs 29:10', 'Proverbs', 29, 10, '&nbsp;د وينو تږى انسانان د نېک انسان نه نفرت کوى او په دې کوشش کښې وى چې صادقان ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16245, 'Proverbs 29:11', 'Proverbs', 29, 11, '&nbsp;کم عقل د خپلې غصې پوره اظهار کوى، خو هوښيار خپل ځان په قابو کښې ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16246, 'Proverbs 29:12', 'Proverbs', 29, 12, '&nbsp;کۀ يو حکمران دروغو ته توجو ورکوى، نو د هغۀ ټول آفسران به بدکاران شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16247, 'Proverbs 29:13', 'Proverbs', 29, 13, '&nbsp;په دې کښې غريب او ظالم دواړه يو شان دى، ځکه مالِک خُدائ دواړو ته ژوندون ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16248, 'Proverbs 29:14', 'Proverbs', 29, 14, '&nbsp;کۀ چرې يو بادشاه د غريبانانو سره اِنصاف کوى، د هغۀ بادشاهى به د تل دپاره قائمه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16249, 'Proverbs 29:15', 'Proverbs', 29, 15, '&nbsp;د تربيت چوکه حِکمت پېدا کوى، خو چې کوم بچے چې آزاد آموخته شى نو هغه به د خپلې مور د شرمولو باعث شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16250, 'Proverbs 29:16', 'Proverbs', 29, 16, '&nbsp;کله چې د بدعمله حکومت راشى، نو ګناهونه عام شى، خو صادقان به د داسې خلقو خاتمه ووينى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16251, 'Proverbs 29:17', 'Proverbs', 29, 17, '&nbsp;د خپل زوئ ښۀ تربيت وکړه هغه به تا ته سکون او خوشحالى درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16252, 'Proverbs 29:18', 'Proverbs', 29, 18, '&nbsp;چرته چې الهام نۀ وى نو هغه خلق سرکشه شى، خو بختور دى هغه څوک چې په شريعت عمل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16253, 'Proverbs 29:19', 'Proverbs', 29, 19, '&nbsp;صرف په خبرو نوکر نۀ سميږى، اګر چې هغه پوهه وى خو بيا هم ستا خبرو ته پام نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16254, 'Proverbs 29:20', 'Proverbs', 29, 20, '&nbsp;څوک چې په جلدۍ کښې خبرې کوى نو هغه د کم عقل نه هم بدتر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16255, 'Proverbs 29:21', 'Proverbs', 29, 21, '&nbsp;کۀ تۀ د ورکوټوالى نه خپل نوکر نيازبين آموخته کړې، نو په آخر کښې به هغه ستا پلار شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16256, 'Proverbs 29:22', 'Proverbs', 29, 22, '&nbsp;غصه ناک انسان جنګونه جوړوى، او تُند خويه نه ډېر ګناهونه کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16257, 'Proverbs 29:23', 'Proverbs', 29, 23, '&nbsp;د انسان غرور په دۀ باندې زوال راولى، خو د انسان عاجز خوى هغۀ ته عزت ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16258, 'Proverbs 29:24', 'Proverbs', 29, 24, '&nbsp;د غلو ملګرے په خپله د ځان دشمن وى، هغه دا چې د قسم خوړلو نه وروستو به هم په عدالت کښې دروغ وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16259, 'Proverbs 29:25', 'Proverbs', 29, 25, '&nbsp;څوک چې د انسان نه يريږى هغه به په دام کښې ګېر شى، خو چې څوک په مالِک خُدائ توکل کوى هغوئ به په امن و امان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16260, 'Proverbs 29:26', 'Proverbs', 29, 26, '&nbsp;ډېر د دې په کوشش کښې وى چې حکمران ورسره ښۀ وى، خو دا د مالِک خُدائ د طرف نه ده چې انسان ته اِنصاف ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16261, 'Proverbs 29:27', 'Proverbs', 29, 27, '&nbsp;نېکان د بې‌ايمانانو نه نفرت کوى، او بدکاران د نېکانو نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16262, 'Proverbs 30:1', 'Proverbs', 30, 1, '&nbsp;د ياقه د زوئ اجور پېغام چې د خُدائ کلام دے. دې سړى پېغام ورکړو ايتى‌اېل ته او ايتى‌اېل اوکال ته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16263, 'Proverbs 30:2', 'Proverbs', 30, 2, '&nbsp;بې‌شکه چې زۀ په ټولو انسانانو کښې بې‌وقوفه يم، ما کښې د انسان په شان عقل نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16264, 'Proverbs 30:3', 'Proverbs', 30, 3, '&nbsp;ما عقل او حِکمت نۀ دے زده کړے، او نۀ ما ته د مقدس ذات په حقله پته شته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16265, 'Proverbs 30:4', 'Proverbs', 30, 4, '&nbsp;آسمان ته څوک تلے او بيا راغلے دے؟ هوا چا په موټى کښې بنده کړې ده؟ او سمندر چا په خپل څادر کښې راګېر کړے دے؟ او د دُنيا حدونه چا مقرر کړى دى؟ د هغۀ نوم څۀ دے او د هغۀ د زوئ نوم څۀ دے؟ کۀ تا ته پته وى نو ما ته يې راوښايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16266, 'Proverbs 30:5', 'Proverbs', 30, 5, '&nbsp;د خُدائ پاک هره خبره قابل اعتماد ده، هغه د هغوئ دپاره ډال دے څوک چې په هغۀ کښې پناه اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16267, 'Proverbs 30:6', 'Proverbs', 30, 6, '&nbsp;د هغۀ د کلام سره اضافه مۀ کوه ځکه چې هغه به دې ورَټى او دروغژن به دې ثابت کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16268, 'Proverbs 30:7', 'Proverbs', 30, 7, '&nbsp;اے مالِکه خُدايه، زۀ د خپل مرګ نه وړاندې ستا نه دوه خواستونه کوم زما خواستونه مۀ رد کوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16269, 'Proverbs 30:8', 'Proverbs', 30, 8, '&nbsp;ما د دروغو او د چل وَل نه وساته مۀ ما غريب کړه او مۀ مې مالداره کړه، خو ما ته صرف خپله د هرې ورځې روټۍ راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16270, 'Proverbs 30:9', 'Proverbs', 30, 9, '&nbsp;هسې نه چې زۀ مالداره شم او تا ونۀ پېژنم او ووايم چې، ”مالِک خُدائ څوک دے؟“ او کۀ يا زۀ غريب شم او غلا وکړم، او داسې د مالِک خُدائ د نوم بې‌عزتى وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16271, 'Proverbs 30:10', 'Proverbs', 30, 10, '&nbsp;د يو نوکر غېبت د هغۀ نېک ته مۀ کوه هسې نه چې د هغۀ لعنت هغه په تا ووائى او دا به ستا دپاره تکليف جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16272, 'Proverbs 30:11', 'Proverbs', 30, 11, '&nbsp;داسې انسانان هم شته چې په خپلو پلارانو لعنت وائى او په خپلو ميندو بدرد وائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16273, 'Proverbs 30:12', 'Proverbs', 30, 12, '&nbsp;خو هغوئ ته خپل ځان صفا ښکارى نو تر اوسه پورې د هغوئ هغه ګندګى لا صفا شوې نۀ ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
