(16275, 'Proverbs 30:14', 'Proverbs', 30, 14, '&nbsp;د هغوئ غاښونه د تُورو په شان دى او د هغوئ ژامنې د چړو په شان دى ترڅو چې غريبانان پرې د زمکې نه تير کړى، او د انسانانو نه ضرورتمند ختم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16276, 'Proverbs 30:15', 'Proverbs', 30, 15, '&nbsp;جوره دوه لوڼه لرى او هر وخت وائى چې، ”راکوه، راکوه.“ په دُنيا کښې درې څيزونه دى چې کله هم نۀ مړيږى، څلور څيزونه دى چې کله هم ”بس“ نۀ وائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16277, 'Proverbs 30:16', 'Proverbs', 30, 16, '&nbsp;قبر، او د شنډې رحم، او اوچه زمکه، او تېز اور.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16278, 'Proverbs 30:17', 'Proverbs', 30, 17, '&nbsp;هغه سترګې چې د خپل پلار پورې ټوقې کوى، او خپلې مور ته سپک ګورى، نو د صحرا په ټپوسانو به راويستلے شى، او لاش به يې د صحرا د ګنجۍ خوراک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16279, 'Proverbs 30:18', 'Proverbs', 30, 18, '&nbsp;په دُنيا کښې درې څيزونه دى چې هغه زما دپاره د حېرانتيا دى، او څلور څيزونه داسې دى چې په هغوئ زۀ پوهه نۀ شوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
