(16282, 'Proverbs 30:21', 'Proverbs', 30, 21, '&nbsp;زمکه د درېو څيزونو په وجه لړزيږى، او څلور څيزونه برداشت کولے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
