(16289, 'Proverbs 30:28', 'Proverbs', 30, 28, '&nbsp;چرمښکۍ په لاس کښې هم رانيولے کېدے شى، خو دا د بادشاهانو په محلونو کښې ګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16290, 'Proverbs 30:29', 'Proverbs', 30, 29, '&nbsp;داسې درې بلکې څلور څيزونه دى چې په ناز ناز قدم اخلى يعنې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
