(16292, 'Proverbs 30:31', 'Proverbs', 30, 31, '&nbsp;هغه چرګ چې ځان ببر کړى، نر چېلے، او بادشاه چې خپل فوجيان ورسره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
