(16300, 'Proverbs 31:6', 'Proverbs', 31, 6, '&nbsp;شراب هغوئ ته ورکړه څوک چې تباه کيږى، او مے د هغوئ دپاره وى څوک چې په غم آخته وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');